#!/usr/bin/env python3
"""Generate the SPYDER Network public research site. Dependency-free, 3 languages.

Source of truth for every page's public HTML. `python3 scripts/build_pages.py`.
All economic numbers in this site are marked preliminary research scenarios.
"""
from pathlib import Path
from html import escape
from datetime import date

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'site'
SITE.mkdir(parents=True, exist_ok=True)
VERSION = '6.0.0'
DOI = '10.5281/zenodo.24435471'
ZENODO = 'https://zenodo.org/records/24435471'
DOI_URL = f'https://doi.org/{DOI}'
ALL_DOI = 'https://doi.org/10.5281/zenodo.24435470'
GITHUB = 'https://github.com/im-ceo-bitch/spyder-network-whitepaper'
RELEASE = GITHUB + '/releases/tag/whitepaper-v0.2.0'
CHAIN = 'https://spyderchain.org/'

def t(en, ru, uz, tag='span', cls=None):
    en,ru,uz=[escape(str(x),quote=True) for x in (en,ru,uz)]
    c=f' class="{cls}"' if cls else ''
    return f'<{tag}{c} data-en="{en}" data-ru="{ru}" data-uz="{uz}">{en}</{tag}>'

def link(href, label, kind='', ext=False):
    extra=' target="_blank" rel="noopener noreferrer"' if ext else ''
    return f'<a class="{kind}" href="{escape(href,quote=True)}"{extra}>{label}</a>'

def eyebrow(en,ru,uz):return f'<p class="eyebrow">{t(en,ru,uz)}</p>'
def p(en,ru,uz,cls='body-copy'):return t(en,ru,uz,'p',cls)
def h2(en,ru,uz):return t(en,ru,uz,'h2')
def h3(en,ru,uz):return t(en,ru,uz,'h3')
def label(en,ru,uz):return t(en,ru,uz,cls='eyebrow-inline')
def action(href,en,ru,uz,style='btn btn-primary',ext=False):
    return link(href,t(en,ru,uz) + '<span aria-hidden="true">↗</span>' if ext else t(en,ru,uz)+'<span aria-hidden="true">→</span>',style,ext)
def trcard(num,title,description,href,cta):
    return f'''<article class="feature-card"><span class="feature-index">{num}</span><div><h3>{title}</h3>{description}</div>{link(href,cta+'<span aria-hidden="true"> ↗</span>','feature-link')}</article>'''
def tag(text,cls='tag'):return f'<span class="{cls}">{escape(text)}</span>'

NAV = [
 ('/',('Overview','Обзор','Bosh sahifa')),
 ('/chain.html',('SpyderChain','SpyderChain','SpyderChain')),
 ('/coin.html',('SpyderCoin','SpyderCoin','SpyderCoin')),
 ('/wallet.html',('Wallet','Кошелёк','Hamyon')),
 ('/whitepaper.html',('Research','Исследования','Tadqiqot')),
 ('/roadmap.html',('Roadmap','План развития','Reja')),
]
FOOT = [('/network.html',('Ecosystem','Экосистема','Ekotizim')),('/security.html',('Security','Безопасность','Xavfsizlik')),('/support.html',('Contact & FAQ','Вопросы и контакты','Savollar va aloqa')),('/privacy.html',('Privacy','Конфиденциальность','Maxfiylik')),('/terms.html',('Terms','Условия','Shartlar'))]

def header(active):
    desktop=''.join(link(href,t(*names),'nav-item'+(' active' if href==active else '')) for href,names in NAV)
